  var HTMLMAP = {"#heroTitle":{"tr":"Güneşten <span class=\"hl\">kazanca</span> dönüşen enerji.","ru":"Энергия солнца, превращённая в <span class=\"hl\">прибыль</span>."},"#calcLead":{"tr":"Sadece faturanızı girin; <strong>sistem gücü, yıllık tasarruf, geri ödeme süresi ve 25 yıllık kazancınızı</strong> saniyeler içinde görün. Üstelik panel yerleşimi, inverter ve kablo gibi <strong>mühendislik araçları</strong> da burada.","ru":"Просто введите свой счёт и за секунды увидите <strong>мощность системы, годовую экономию, срок окупаемости и доход за 25 лет</strong>. А также <strong>инженерные инструменты</strong> для раскладки модулей, инвертора и кабеля."},"#shopNoJs":{"tr":"Ürünleri görüntülemek için JavaScript'i etkinleştirin veya <a href=\"iletisim.html\">bizimle iletişime geçin</a>.","ru":"Включите JavaScript, чтобы увидеть товары, или <a href=\"iletisim.html\">свяжитесь с нами</a>."},"#ordConsent":{"tr":"Siparişi göndererek <a href=\"/kvkk.html\">KVKK Aydınlatma Metni</a>'ni ve aşağıdaki satış şartlarını kabul etmiş olursunuz.","ru":"Отправляя заказ, вы принимаете <a href=\"/kvkk.html\">Уведомление о персональных данных (KVKK)</a> и условия продажи ниже."}};
